<template><div class="guide-shade"><section class="guide"><div class="guide-progress"><span v-for="(_,i) in steps" :key="i" :class="{done:i<=step}"/></div><span class="fm-kicker">首次使用引导 · {{step+1}} / {{steps.length}}</span><h2>{{current.title}}</h2><p>{{current.description}}</p><div class="guide-actions"><button class="skip" @click="skipAll">跳过全部引导</button><button class="skip" @click="next">跳过这一步</button><FmButton variant="primary" @click="go">{{onPage?'完成这一步':current.action}}</FmButton></div></section></div></template>
<script setup>import{computed,ref}from"vue";import{useRoute,useRouter}from"vue-router";import{api,session,toast}from"../api/client.js";import FmButton from"../ui/freemodel/components/FmButton.vue";const emit=defineEmits(["done"]),router=useRouter(),route=useRoute(),step=ref(0),steps=[{title:"先连接你的站点",description:"添加自己的 New API 或 Sub2API，系统会自动读取分组和账号。",action:"去添加站点",path:"/sites"},{title:"再添加一个上游",description:"只需要普通 Key，系统会先检查它是否支持监听。",action:"去添加上游",path:"/sources"},{title:"创建同步任务",description:"选择目标分组并填写利润调整值，之后就会自动监听。",action:"去创建任务",path:"/tasks"}];const current=computed(()=>steps[step.value]),onPage=computed(()=>route.path===current.value.path);async function complete(){try{session.user=await api("/api/me/onboarding",{method:"PUT",body:JSON.stringify({completed:true})});emit("done")}catch(e){toast(e.message,"error")}}function next(){if(step.value>=steps.length-1)complete();else step.value++}function go(){if(onPage.value)next();else router.push(current.value.path)}function skipAll(){complete()}</script>
<style scoped>.guide-shade{position:fixed;inset:0;z-index:1100;display:grid;place-items:end end;padding:28px;pointer-events:none}.guide{width:min(460px,100%);padding:24px;border:1px solid var(--fm-line);border-radius:16px;background:var(--fm-bg-card);box-shadow:var(--fm-modal-shadow);pointer-events:auto}.guide-progress{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:20px}.guide-progress span{height:4px;border-radius:3px;background:var(--fm-line)}.guide-progress span.done{background:var(--fm-accent)}.guide h2{margin:7px 0;font-size:22px}.guide p{margin:0 0 20px;color:var(--fm-ink-soft)}.guide-actions{display:flex;align-items:center;justify-content:flex-end;gap:9px}.skip{padding:8px;background:transparent;color:var(--fm-ink-muted);font-size:12px}@media(max-width:600px){.guide-shade{padding:12px}.guide{width:100%}.guide-actions{align-items:stretch;flex-direction:column}.skip{order:2}}</style>
